935:             root.addItem(null);
936:             fail("Expected exception");
937:         }
938:         catch (NullPointerException e) {
939:             assertEquals("A composite item child can not be null", e.getMessage());
940:         }
941: 
942:         try {
943:             root.addItem(root);
