960:         try {
961:             OrItem child = new OrItem();
962:             root.addItem(child);
963:             child.addItem(root);
964:             fail("Expected exception");
965:         }
966:         catch (IllegalArgumentException e) {
967:             assertEquals("Cannot add '(AND (OR ))' to '(OR )' as it would create a cycle", e.getMessage());
