413:   public static GatewayStub buildGatewayStub(
414:       final ManagedChannel channel, final CamundaClientConfiguration config) {
415:     final CallCredentials credentials = buildCallCredentials(config);
416:     final GatewayStub gatewayStub = GatewayGrpc.newStub(channel).withCallCredentials(credentials);
417:     if (!config.getInterceptors().isEmpty()) {
418:       return gatewayStub.withInterceptors(
419:           config.getInterceptors().toArray(new ClientInterceptor[] {}));
420:     }
421:     return gatewayStub;
422:   }
