424:   private static Map<String, Object> defaultServiceConfig() {
425:     final ObjectMapper objectMapper = new ObjectMapper();
426:     final URL defaultServiceConfig =
427:         ClassLoader.getSystemClassLoader().getResource("gateway-service-config.json");
428:     if (defaultServiceConfig == null) {
429:       Loggers.LOGGER.info(
430:           "No default service config found on classpath; will not configure a default retry policy");
431:       return new HashMap<>();
432:     }
433: 
434:     try {
435:       return objectMapper.readValue(
436:           defaultServiceConfig, new TypeReference<Map<String, Object>>() {});
437:     } catch (final IOException e) {
438:       Loggers.LOGGER.warn(
439:           "Failed to read default service config from classpath; will not configure a default retry policy",
440:           e);
441:       return new HashMap<>();
442:     }
443:   }
